package dev.raf.radar;
import android.app.*;import android.content.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;
final class AccountUi {
 static EditText field(MainActivity a,LinearLayout box,String hint,boolean secret){EditText e=new EditText(a);e.setSingleLine(true);e.setHint(hint);e.setTextColor(a.fg);e.setHintTextColor(a.muted);e.setInputType(secret?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT);box.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 static void choose(MainActivity a){if(a.isFinishing()||a.isDestroyed()||AccountClient.active(a.store)||(a.accountDialog!=null&&a.accountDialog.isShowing()))return;
  a.accountDialog=new AlertDialog.Builder(a).setTitle("SENSE PRO · аккаунт").setMessage("Выберите регистрацию нового аккаунта или вход по ID и паролю.").setCancelable(false).setPositiveButton("Регистрация",(d,w)->form(a,"register")).setNegativeButton("Вход",(d,w)->form(a,"login")).create();a.accountDialog.show();}
 static void form(MainActivity a,String mode){boolean register=mode.equals("register"),recover=mode.equals("recover");LinearLayout box=a.column();box.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(8));
  EditText id=field(a,box,register?"ID 1–999 · пусто = случайный":"Ваш ID",false);id.setInputType(InputType.TYPE_CLASS_NUMBER);id.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(3)});
  if(register)box.addView(a.text("Свободный номер проверяется при регистрации",11,a.muted));
  EditText code=recover?field(a,box,"Код восстановления · 16 цифр",true):null;
  EditText password=field(a,box,recover?"Новый пароль · от 8 символов":"Пароль · от 8 символов",true);EditText confirm=register||recover?field(a,box,"Повторите пароль",true):null;
  TextView error=a.text("",12,0xFFFF8888);box.addView(error);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(register?"Регистрация":recover?"Восстановление доступа":"Вход").setView(box).setCancelable(false).setPositiveButton(register?"Зарегистрироваться":recover?"Восстановить":"Войти",null).setNegativeButton("Назад",(d,w)->{a.accountDialog=null;choose(a);}).setNeutralButton(!register&&!recover?"Забыл пароль":null,(d,w)->form(a,"recover")).create();a.accountDialog=dialog;dialog.show();
  dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String pass=password.getText().toString();String number=id.getText().toString();if((!register&&number.isEmpty())||(!number.isEmpty()&&(Integer.parseInt(number)<1))){error.setText("ID от 1 до 999");return;}if(pass.length()<8||pass.length()>128){error.setText("Пароль от 8 до 128 символов");return;}if(confirm!=null&&!pass.equals(confirm.getText().toString())){error.setText("Пароли не совпадают");return;}
   JSONObject body=AccountClient.action(mode);try{body.put("password",pass);if(!number.isEmpty())body.put("id",Integer.parseInt(number));if(register){body.put("name",a.store.prefs.getString("profileName",""));String legacy=a.store.prefs.getString("presenceToken",null);if(legacy!=null)body.put("legacyToken",legacy);}if(recover)body.put("code",code.getText().toString().replace(" ",""));}catch(JSONException e){throw new IllegalStateException(e);}
   dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(false);error.setText("Подключение…");AccountClient.call(a,body,(data,message)->{if(a.isDestroyed())return;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(true);if(message!=null){error.setText(message);return;}password.setText("");if(confirm!=null)confirm.setText("");dialog.dismiss();a.friends.clear();a.peers.clear();a.refreshCards();a.rebuildSettings();if(data.has("recoveryCode"))recovery(a,data.optString("recoveryCode",""));else if(a.store.prefs.getString("profileName","").isEmpty())a.editName(true);});
  });
 }
 static void recovery(MainActivity a,String code){TextView text=a.text("ID: "+a.store.prefs.getInt("accountId",0)+"\n\n"+code+"\n\nСохраните код или сделайте скриншот. Он заменяет пароль при восстановлении. После использования будет выдан новый код.",16,a.fg);text.setTextIsSelectable(true);text.setPadding(a.dp(24),a.dp(16),a.dp(24),a.dp(16));new AlertDialog.Builder(a).setTitle("Код восстановления").setView(text).setCancelable(false).setNeutralButton("Скопировать",(d,w)->{((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("SENSE PRO · код восстановления",code));recovery(a,code);}).setPositiveButton("Сохранил",(d,w)->{if(a.store.prefs.getString("profileName","").isEmpty())a.editName(true);}).show();}
 static void password(MainActivity a){LinearLayout box=a.column();box.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(8));EditText old=field(a,box,"Старый пароль",true),next=field(a,box,"Новый пароль",true),confirm=field(a,box,"Повторите новый пароль",true);TextView error=a.text("",12,0xFFFF8888);box.addView(error);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Изменить пароль").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Изменить",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String pass=next.getText().toString();if(!pass.equals(confirm.getText().toString())||pass.length()<8||pass.length()>128){error.setText("Проверьте новый пароль и подтверждение");return;}JSONObject body=AccountClient.action("password");try{body.put("oldPassword",old.getText().toString()).put("password",pass);}catch(JSONException e){throw new IllegalStateException(e);}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);AccountClient.call(a,body,(data,message)->{if(a.isDestroyed())return;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);if(message!=null)error.setText(message);else{old.setText("");next.setText("");confirm.setText("");dialog.dismiss();a.toast("Пароль изменён. На других устройствах войдите снова");}});});}
}
